import { SchedulerLike, ReadableStreamLike } from '../types';
import { Observable } from '../Observable';
import { scheduleAsyncIterable } from './scheduleAsyncIterable';
import { readableStreamLikeToAsyncGenerator } from '../util/isReadableStreamLike';

export function scheduleReadableStreamLike<T>(input: ReadableStreamLike<T>, scheduler: SchedulerLike): Observable<T> {
  return scheduleAsyncIterable(readableStreamLikeToAsyncGenerator(input), scheduler);
}

import { expect } from 'chai';
import { firstValueFrom, scheduled, asyncScheduler } from 'rxjs';
import { readableStreamLikeToAsyncGenerator } from '../src/internal/util/isReadableStreamLike';
describe('stream lifecycle regression', () => {
  function fixture() {
    const state = { canceled: 0, released: 0 };
    const stream = { getReader: () => ({ read: async () => ({ done: false as const, value: 1 }), cancel: async () => { state.canceled++; }, releaseLock: () => { state.released++; } }) };
    return { state, stream };
  }
  it('cancels and releases on direct early iterator return', async () => {
    const { state, stream } = fixture();
    const iterator = readableStreamLikeToAsyncGenerator(stream);
    await iterator.next(); await iterator.return();
    expect(state).to.deep.equal({ canceled: 1, released: 1 });
  });
  it('scheduled early subscription close also cleans up', async () => {
    const { state, stream } = fixture();
    expect(await firstValueFrom(scheduled(stream, asyncScheduler))).to.equal(1);
    await new Promise(resolve => setTimeout(resolve, 25));
    expect(state).to.deep.equal({ canceled: 1, released: 1 });
  });
});

import { SchedulerLike } from '../types';
import { Observable } from '../Observable';
import { executeSchedule } from '../util/executeSchedule';

export function scheduleAsyncIterable<T>(input: AsyncIterable<T>, scheduler: SchedulerLike) {
  if (!input) {
    throw new Error('Iterable cannot be null');
  }
  return new Observable<T>((subscriber) => {
    executeSchedule(subscriber, scheduler, () => {
      const iterator = input[Symbol.asyncIterator]();
      executeSchedule(
        subscriber,
        scheduler,
        () => {
          iterator.next().then((result) => {
            if (result.done) {
              // This will remove the subscriptions from
              // the parent subscription.
              subscriber.complete();
            } else {
              subscriber.next(result.value);
            }
          });
        },
        0,
        true
      );
    });
  });
}

import { ReadableStreamLike } from '../types';
import { isFunction } from './isFunction';

export async function* readableStreamLikeToAsyncGenerator<T>(readableStream: ReadableStreamLike<T>): AsyncGenerator<T> {
  const reader = readableStream.getReader();
  try {
    while (true) {
      const { value, done } = await reader.read();
      if (done) {
        return;
      }
      yield value!;
    }
  } finally {
    reader.releaseLock();
  }
}

export function isReadableStreamLike<T>(obj: any): obj is ReadableStreamLike<T> {
  // We don't want to use instanceof checks because they would return
  // false for instances from another Realm, like an <iframe>.
  return isFunction(obj?.getReader);
}

