114 |    * @param teardown The finalization logic to add to this subscription.
115 |    */
116 |   add(teardown: TeardownLogic): void {
117 |     // Only add the finalizer if it's not undefined
118 |     // and don't add a subscription to itself.
119 |     if (teardown && teardown !== this) {
120 |       if (this.closed) {
121 |         // If this subscription is already closed,
122 |         // execute whatever finalizer is handed to it automatically.
123 |         execFinalizer(teardown);
124 |       } else {
