  if (!input) {
    throw new Error('Iterable cannot be null');
  }
  return new Observable<T>((subscriber) => {
    let iterator: AsyncIterator<T> | undefined;
    let completed = false;
    let iteratorReturned = false;

    const returnIterator = () => {
      if (iterator && !iteratorReturned) {
        iteratorReturned = true;
        if (typeof iterator.return === 'function') {
          try {
            Promise.resolve(iterator.return()).then(undefined, () => undefined);
          } catch {
            // Ignore errors from iterator.return during unsubscription.
          }
        }
      }
    };

    const scheduleNext = () => {
      if (subscriber.closed || completed) {
        return;
      }
      executeSchedule(subscriber, scheduler, () => {
        if (subscriber.closed || completed) {
          return;
        }

        let nextResult: PromiseLike<IteratorResult<T>>;
        try {
          nextResult = iterator!.next();
        } catch (err) {
          completed = true;
          subscriber.error(err);
          return;
        }

        Promise.resolve(nextResult).then(
          (result) => {
            if (subscriber.closed || completed) {
              return;
            }
            if (result.done) {
              completed = true;
              subscriber.complete();
            } else {
              subscriber.next(result.value);
              scheduleNext();
            }
          },
          (err) => {
            if (subscriber.closed || completed) {
              return;
            }
            completed = true;
            subscriber.error(err);
          }
        );
      });
    };

    executeSchedule(subscriber, scheduler, () => {
      if (subscriber.closed) {
        return;
      }
      iterator = input[Symbol.asyncIterator]();
      scheduleNext();
    });

    return () => {
      if (!completed) {
        returnIterator();
      }
    };
  });
}

