172 | 
173 |     case "string":
174 |       return ZodParsedType.string;
175 | 
176 |     case "number":
177 |       return isNaN(data) ? ZodParsedType.nan : ZodParsedType.number;
178 | 
179 |     case "boolean":
180 |       return ZodParsedType.boolean;
181 | 
182 |     case "function":
183 |       return ZodParsedType.function;
184 | 
185 |     case "bigint":
