187 | 
188 |     case "symbol":
189 |       return ZodParsedType.symbol;
190 | 
191 |     case "object":
192 |       if (Array.isArray(data)) {
193 |         return ZodParsedType.array;
194 |       }
195 |       if (data === null) {
196 |         return ZodParsedType.null;
197 |       }
198 |       if (
199 |         data.then &&
