 268 |   "~validate"(
 269 |     data: unknown
 270 |   ):
 271 |     | StandardSchemaV1.Result<Output>
 272 |     | Promise<StandardSchemaV1.Result<Output>> {
 273 |     const ctx: ParseContext = {
 274 |       common: {
 275 |         issues: [],
 276 |         async: !!(this["~standard"] as any).async,
 277 |       },
 278 |       path: [],
 279 |       schemaErrorMap: this._def.errorMap,
 280 |       parent: null,
 281 |       data,
 282 |       parsedType: getParsedType(data),
 283 |     };
 284 | 
 285 |     if (!(this["~standard"] as any).async) {
 286 |       try {
 287 |         const result = this._parseSync({ data, path: [], parent: ctx });
 288 |         return isValid(result)
 289 |           ? {
 290 |               value: result.value,
 291 |             }
 292 |           : {
 293 |               issues: ctx.common.issues,
 294 |             };
 295 |       } catch (err: any) {
 296 |         if ((err as Error)?.message?.toLowerCase()?.includes("encountered")) {
 297 |           (this["~standard"] as any).async = true;
 298 |         }
 299 |         (ctx as any).common = {
 300 |           issues: [],
 301 |           async: true,
 302 |         };
 303 |       }
 304 |     }
 305 | 
 306 |     return this._parseAsync({ data, path: [], parent: ctx }).then((result) =>
 307 |       isValid(result)
 308 |         ? {
 309 |             value: result.value,
 310 |           }
 311 |         : {
 312 |             issues: ctx.common.issues,
 313 |           }
 314 |     );
 315 |   }
