 353 |   refine<RefinedOutput extends Output>(
 354 |     check: (arg: Output) => arg is RefinedOutput,
 355 |     message?: string | CustomErrorParams | ((arg: Output) => CustomErrorParams)
 356 |   ): ZodEffects<this, RefinedOutput, Input>;
 357 |   refine(
 358 |     check: (arg: Output) => unknown | Promise<unknown>,
