 361 |   refine(
 362 |     check: (arg: Output) => unknown,
 363 |     message?: string | CustomErrorParams | ((arg: Output) => CustomErrorParams)
 364 |   ): ZodEffects<this, Output, Input> {
 365 |     const getIssueProperties = (val: Output) => {
 366 |       if (typeof message === "string" || typeof message === "undefined") {
 367 |         return { message };
 368 |       } else if (typeof message === "function") {
 369 |         return message(val);
 370 |       } else {
 371 |         return message;
 372 |       }
 373 |     };
 374 |     return this._refinement((val, ctx) => {
 375 |       const result = check(val);
 376 |       const setError = () =>
 377 |         ctx.addIssue({
 378 |           code: ZodIssueCode.custom,
 379 |           ...getIssueProperties(val),
 380 |         });
 381 |       if (typeof Promise !== "undefined" && result instanceof Promise) {
 382 |         return result.then((data) => {
 383 |           if (!data) {
 384 |             setError();
 385 |             return false;
 386 |           } else {
 387 |             return true;
 388 |           }
 389 |         });
 390 |       }
 391 |       if (!result) {
 392 |         setError();
 393 |         return false;
 394 |       } else {
 395 |         return true;
 396 |       }
 397 |     });
 398 |   }
