72 | export function appendIssueToContext(
73 |   ctx: ParseContext,
74 |   issueData: IssueData
75 | ): void {
76 |   const overrideMap = getErrorMap();
77 |   const issue = makeIssue({
78 |     issueData: issueData,
79 |     data: ctx.data,
80 |     path: ctx.path,
81 |     errorMaps: [
82 |       ctx.common.contextualErrorMap, // contextual error map is first priority
83 |       ctx.schemaErrorMap, // then schema-bound map if available
84 |       overrideMap, // then global override map
85 |       overrideMap === defaultErrorMap ? undefined : defaultErrorMap, // then global default map
86 |     ].filter((x) => !!x) as ZodErrorMap[],
87 |   });
88 |   ctx.common.issues.push(issue);
89 | }
