  92 | const handleResult = <Input, Output>(
  93 |   ctx: ParseContext,
  94 |   result: SyncParseReturnType<Output>
  95 | ):
  96 |   | { success: true; data: Output }
  97 |   | { success: false; error: ZodError<Input> } => {
  98 |   if (isValid(result)) {
