 100 |   } else {
 101 |     if (!ctx.common.issues.length) {
 102 |       throw new Error("Validation failed but no issues detected.");
 103 |     }
 104 | 
 105 |     return {
 106 |       success: false,
 107 |       get error() {
 108 |         if ((this as any)._error) return (this as any)._error as Error;
 109 |         const error = new ZodError(ctx.common.issues);
 110 |         (this as any)._error = error;
 111 |         return (this as any)._error;
 112 |       },
 113 |     };
 114 |   }
