 130 | function processCreateParams(params: RawCreateParams): ProcessedCreateParams {
 131 |   if (!params) return {};
 132 |   const { errorMap, invalid_type_error, required_error, description } = params;
 133 |   if (errorMap && (invalid_type_error || required_error)) {
 134 |     throw new Error(
 135 |       `Can't use "invalid_type_error" or "required_error" in conjunction with custom error map.`
 136 |     );
 137 |   }
 138 |   if (errorMap) return { errorMap: errorMap, description };
 139 |   const customMap: ZodErrorMap = (iss, ctx) => {
 140 |     const { message } = params;
 141 | 
 142 |     if (iss.code === "invalid_enum_value") {
 143 |       return { message: message ?? ctx.defaultError };
 144 |     }
 145 |     if (typeof ctx.data === "undefined") {
 146 |       return { message: message ?? required_error ?? ctx.defaultError };
 147 |     }
 148 |     if (iss.code !== "invalid_type") return { message: ctx.defaultError };
 149 |     return { message: message ?? invalid_type_error ?? ctx.defaultError };
 150 |   };
 151 |   return { errorMap: customMap, description };
 152 | }
